package org.intelehealth.ezazi.stage3.dbimport org.intelehealth.ezazi.models.dto.EncounterDTOimport org.intelehealth.ezazi.stage3.models.DeliveryDetailsclass DeliveryRepository(    private val localDataSource: DeliveryLocalDataSource,    private val mapper: DeliveryObsMapper) {    private val TAG = "DeliveryRepository"    fun saveDeliveryDetails(encounterDTO: EncounterDTO, deliveryDetails: DeliveryDetails, creatorUuid: String): Boolean {        //  insert encounter- Women delivery outcome        val isEncounterInserted = localDataSource.insertEncounter(encounterDTO)        if (!isEncounterInserted) {            return false        }        val obsList = mapper.mapToObsList(encounterDTO.uuid, deliveryDetails, creatorUuid)        //VisitsDAO().updateVisitSync(mVisitUUID, "false")        // insert Obs        return localDataSource.saveDeliveryObsData(obsList)    }}